String text = '  Trail cabin trail  ';
String trimmed = text.trim();
System.assertEquals('Trail cabin trail', trimmed);
System.assert(trimmed.startsWith('Trail'));
System.assert(trimmed.endsWith('trail'));
System.assert('Cabin'.equalsIgnoreCase('cabin'));
System.assertEquals(6, trimmed.indexOf('cabin'));
System.assertEquals(12, trimmed.lastIndexOf('trail'));
System.assertEquals(17, trimmed.length());
System.assertEquals('Trail cabin path', trimmed.replace('trail', 'path'));
System.assertEquals('cabin', trimmed.substring(6, 11));
System.assertEquals('trail cabin trail', trimmed.toLowerCase());
System.assertEquals('TRAIL CABIN TRAIL', trimmed.toUpperCase());
System.assert(String.isBlank('   '));
System.assert(!String.isNotBlank('   '));
System.assert(String.isNotBlank('spruce'));
System.assertEquals('one/two/three', String.join(new List<String>{'one', 'two', 'three'}, '/'));
System.assertEquals('42', String.valueOf(42));
System.assertEquals(5, Math.abs(-5));
System.assertEquals(3.0, Math.ceil(2.1));
System.assertEquals(2.0, Math.floor(2.9));
System.assertEquals(7, Math.max(3, 7));
System.assertEquals(3, Math.min(3, 7));
System.assertEquals(8.0, Math.pow(2, 3));
System.assertEquals(2, Math.round(2.5));
System.assertEquals(3.0, Math.sqrt(9));
Date day = Date.newInstance(2024, 2, 28);
System.assertEquals('2024-02-29', String.valueOf(day.addDays(1)));
Datetime stamp = Datetime.valueOf('2024-02-29 01:02:03');
System.assertEquals(3, stamp.addHours(2).hour());
System.assertEquals(7, stamp.addMinutes(5).minute());
System.assertEquals(13, stamp.addSeconds(10).second());
System.assert(String.valueOf(stamp).startsWith('2024-02-29 01:02:03'));
Time clock = Time.newInstance(3, 4, 5, 6);
System.assertEquals(3, clock.hour());
System.assertEquals(4, clock.minute());
System.assertEquals(5, clock.second());
Blob hello = Blob.valueOf('hello');
System.assertEquals('aGVsbG8=', EncodingUtil.base64Encode(hello));
System.assertEquals('68656c6c6f', EncodingUtil.convertToHex(hello));
String encoded = EncodingUtil.urlEncode('A B+', 'UTF-8');
System.assertEquals('A+B%2B', encoded);
System.assertEquals('A B+', EncodingUtil.urlDecode(encoded, 'UTF-8'));
Blob digest = Crypto.generateDigest('SHA-256', hello);
System.assertEquals('2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824', EncodingUtil.convertToHex(digest));

